#include <iostream>
#include <cstdint>
int main() {
    uint32_t a = 0b10101101;  // Binary: 1010 1101
    uint32_t b = 0b11001100;  // Binary: 1100 1100
    uint32_t result = a & b;  // Binary result: 1010 1101 & 1100 1100 = 1000 1100
    std::cout << std::hex << result << std::endl;  // Outputs: 8c (in hexadecimal)
    return 0;
}
